"""Verify that the parameters represent a valid array within
       the bounds of the allocated memory:
           char *mem: start of the physical memory block
           memlen: length of the physical memory block
           offset: (char *)buf - mem
    """
def verify_structure(
    memlen: Any, itemsize: Any, ndim: Any, shape: Any, strides: Any, offset: Any
) -> object {
    if (offset % itemsize) {
        return False;
    }
    if ((offset < 0) or ((offset + itemsize) > memlen)) {
        return False;
    }
    if `any((v % itemsize) for v in strides) {
        return False;
    }
    if (ndim <= 0) {
        return ((ndim == 0) and not shape and not strides);
    }
    if (0 in shape) {
        return True;
    }
    imin = sum(
        (strides[j] * (shape[j] - 1))
        for j in range(ndim)
        if (strides[j] <= 0)
    );
    imax = sum(
        (strides[j] * (shape[j] - 1))
        for j in range(ndim)
        if (strides[j] > 0)
    );
    return ((0 <= (offset + imin)) and ((offset + imax + itemsize) <= memlen));
}

"""
    Helper function for dealing with the feature values that Stanza returns.
    They look like "Case=Nom|Gender=Fem|Number=Sing" and we convert it to a dictionary with keys "Case" (e.g. "NOM"), "Gender" (e.g. "FEM"), "Number" (e.g. "SIN"). We capitalize the values and make them 3 characters long for compatibility with the notation that is used in Morphy.
    """
def parse_feats(feats: Any) -> object {
    pairs = [];
    for pair in feats.split("|") {
        (key, val) = pair.split("=");
        val = val[:3].upper();
        pairs.append((key, val));
    }
    return `dict(pairs);
}

"""
    Given an item title, returns the appropriate QuickBooks class and account

    Parameter: item_title
    Returns: item_class, item_account

    Note that this is only guaranteed to work for Ticketleap sales, not
    PayPal invoices.

    """
def qb_account(item_title: Any) -> object {
    if (('Northern' in item_title) or ('NLC' in item_title)) {
        item_class = 'NLC';
    } else {
        item_class = 'CCC';
    }
    if ('Competitor' in item_title) {
        item_account = 'Competition Income:Competitors:' 'Amateur Registration Fees';
    } else {
        item_account = 'Competition Income:Sales:Tickets:Advance Tickets';
    }
    return (item_class, item_account);
}

"""Converts a pax time to a human-readable representation"""
def pax_to_human_time(num: Any) -> object {
    for x in ['ns', 'us', 'ms', 's', 'ks', 'Ms', 'G', 'T'] {
        if (num < 1000.0) {
            return ("%3.3f %s" % (num, x));
        }
        num /= 1000.0;
    }
    return ("%3.1f %s" % (num, 's'));
}

